# Let me manually check potential patterns by looking at character differences
inputs = ['cv', 'fubw', 'ucfvyj', 'hxhju', 'agazj']
outputs = ['cuvf', 'fubvjg', 'ucfuvfyj', 'uvfxuvfju', 'gugguzj']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{i+1}. '{inp}' → '{outp}'")
    print(f"   Length: {len(inp)} → {len(outp)}")

    # Look for common substrings or patterns
    if i == 0:
        print(f"   Diff: v→uvf")
    elif i == 1:
        print(f"   Diff: w→vjg")
    elif i == 2:
        print(f"   Diff: vy→uvf")
    elif i == 3:
        print(f"   Diff: h→uvf, j→u")
    elif i == 4:
        print(f"   Diff: a→gu, z→guz")
    print()

